// A recall on batch B7 of GTIN 08901234567895 — need to find all affected SGTINs
// and their current downstream locations.

class RecallInvestigator {
  final EpcisRepo _repo;
  RecallInvestigator(this._repo);

  Future<RecallReport> investigate({required String gtin, required String batch}) async {
    // 1. Find all SGTINs commissioned in that (GTIN, batch)
    final sgtins = await _repo.querySgtins(gtin: gtin, batch: batch);

    // 2. For each SGTIN, walk the event chain to find current bizLocation
    final rows = <RecallRow>[];
    for (final s in sgtins) {
      final chain = await _repo.getEventChain(s);
      final last = chain.lastWhere(
        (e) => e.bizStep != 'dispense',   // dispense = out of trace
        orElse: () => chain.last,
      );
      rows.add(RecallRow(
        sgtin: s,
        currentLocation: last.bizLocation,
        disposition: last.disposition,
        events: chain.length,
      ));
    }

    // 3. Group by current location → dispatch recall notices
    final byLocation = groupBy(rows, (r) => r.currentLocation);
    return RecallReport(byLocation);
  }
}

